export function InteriorPage({ eyebrow, title, description, children, dark = false }: { eyebrow: string; title: string; description?: string; children?: React.ReactNode; dark?: boolean }) {
  return <AlbaLayout dark><section className={`${heroBlock} ${dark ? "" : "!min-h-[360px] !pb-12"}`}><div className="alba-wrap relative z-10"><p className="alba-eyebrow">{eyebrow}</p><h1 className="editorial-title mt-4 max-w-3xl text-5xl sm:text-7xl">{title}</h1>{description && <p className="mt-5 max-w-xl text-sm leading-7 text-ivory/70">{description}</p>}</div></section>{children}</AlbaLayout>;
}

export function AboutPage() {
  return <InteriorPage eyebrow="The ALBA way" title="A softer pace. A deeper kind of care." description="An intimate Korean-inspired head spa, created for the moments when you need to return to yourself.">
    <section className="alba-section"><div className="alba-wrap grid gap-12 lg:grid-cols-2 lg:items-center"><AlbaImage src="interior" alt="ALBA Wellness treatment room" className="aspect-[4/3] w-full object-cover"/><div><p className="alba-eyebrow">Our story</p><h2 className="editorial-title mt-4 text-5xl">Care that starts at the roots.</h2><p className="mt-6 text-sm leading-7 text-muted-foreground">ALBA began with a simple belief: feeling well can start with making space for one small, unhurried thing. Inspired by the care and intention of the Korean head spa, we made a private sanctuary where scalp wellness and full-body relaxation meet.</p><p className="mt-4 text-sm leading-7 text-muted-foreground">Our vision is a gentler kind of wellness. Our mission is to make every visit feel personal, considered and easy to return to.</p></div></div></section>
    <section className="alba-section dark-panel"><div className="alba-wrap grid gap-8 sm:grid-cols-3">{[["Thoughtful touch", "Techniques chosen for comfort, not a one-size-fits-all routine."], ["A calm of your own", "A quiet private room, warmed towels and time without hurry."], ["Care in the details", "Premium products, attentive therapists and a ritual shaped around you."]].map(([title, text]) => <article key={title} className="border-t border-champagne/60 pt-5"><p className="font-display text-3xl">{title}</p><p className="mt-3 text-sm leading-6 text-ivory/60">{text}</p></article>)}</div></section>
    <section className="alba-section"><div className="alba-wrap flex flex-col items-start justify-between gap-7 sm:flex-row sm:items-end"><SectionHeading eyebrow="Our approach" title="A ritual, never a routine." body="Your therapist listens first, then adapts the pressure, products and pace to what feels right for you."/><Button asChild className="rounded-none"><Link to="/booking">MEET YOUR MOMENT <ArrowRight/></Link></Button></div></section>
  </InteriorPage>;
}

export function ServicesPage() {
  const { store } = useAlbaDemo();
  const [filter, setFilter] = useState("All");
  const filters = ["All", "Head Spa", "Scalp Care", "Relaxation", "Wellness", "Packages"];
  const services = store.services.filter((service) => service.active && (filter === "All" || service.category === filter));
  return <InteriorPage eyebrow="Treatments" title="Find the ritual that feels right." description="Considered head spa and scalp rituals, each shaped to help you feel more rested, more balanced, more yourself.">
    <section className="alba-section"><div className="alba-wrap"><div className="flex flex-wrap gap-2" role="group" aria-label="Filter treatments">{filters.map((item) => <Button key={item} onClick={() => setFilter(item)} variant={filter === item ? "default" : "outline"} className="h-9 rounded-none px-4 text-xs">{item}</Button>)}</div><div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{services.map((service) => <AlbaServiceCard key={service.id} service={service}/>)}</div>{services.length === 0 && <p className="py-16 text-center text-sm text-muted-foreground">There are no treatments in this collection right now.</p>}</div></section>
  </InteriorPage>;
}

export function ServiceDetailPage({ serviceId }: { serviceId?: string }) {
  const params = useParams({ strict: false }) as { serviceId?: string };
  const { store } = useAlbaDemo();
  const service = getService(store, serviceId ?? params.serviceId ?? "signature");
  const image = albaImages[service.image as keyof typeof albaImages] ?? albaImages.treatment;
  return <InteriorPage eyebrow={service.category} title={service.name} description={service.description}>
    <section className="alba-section"><div className="alba-wrap grid gap-12 lg:grid-cols-[1.1fr_0.9fr] lg:items-start"><AlbaImage src={service.image} alt={service.name} className="aspect-[4/3] w-full object-cover"/><div><div className="flex flex-wrap gap-5 text-xs text-muted-foreground"><span className="inline-flex items-center gap-2"><Clock3 className="size-4 text-forest"/>{service.duration} minutes</span><span className="inline-flex items-center gap-2"><Sparkles className="size-4 text-forest"/>Personalised ritual</span></div><p className="mt-5 font-display text-5xl">{formatRupees(service.discountPrice || service.price)}</p><p className="mt-4 text-sm leading-7 text-muted-foreground">{service.description}</p><p className="mt-3 text-sm text-muted-foreground">Recommended for {service.recommended ?? "guests who want a private, unhurried reset"}.</p><div className="mt-7"><p className="alba-eyebrow">The feeling after</p><div className="mt-3 grid gap-2">{service.benefits.map((benefit) => <p key={benefit} className="flex items-center gap-2 text-sm"><Check className="size-4 text-forest"/>{benefit}</p>)}</div></div><div className="mt-7"><p className="alba-eyebrow">How the ritual unfolds</p><div className="mt-3 grid gap-2 text-sm text-muted-foreground">{["A quiet welcome and a short consultation", "Gentle scalp cleanse and warm water therapy", "Personalised massage at your preferred pressure", "A nourishing finish and time to re-enter the day"].map((step, index) => <p key={step}>{index + 1}. {step}</p>)}</div></div><div className="mt-7"><p className="alba-eyebrow">Included</p><p className="mt-3 text-sm leading-7 text-muted-foreground">Private treatment room, warmed towels, chosen products and the full {service.duration}-minute ritual.</p></div><div className="mt-7"><p className="alba-eyebrow">Optional additions</p><div className="mt-3 grid gap-2">{service.addOns.map((addon) => <p key={addon.name} className="flex justify-between text-sm"><span>{addon.name}</span><span>+{formatRupees(addon.price)}</span></p>)}</div></div><div className="mt-7"><p className="alba-eyebrow">Questions</p><div className="mt-3 grid gap-3">{store.faqs.filter((faq) => faq.published).map((faq) => <div key={faq.id}><p className="text-sm font-medium">{faq.question}</p><p className="mt-1 text-sm text-muted-foreground">{faq.answer}</p></div>)}</div></div><Button asChild className="mt-8 h-12 w-full rounded-none"><Link to="/booking" search={{ service: service.id }}>BOOK THIS TREATMENT <ArrowRight/></Link></Button><p className="mt-3 text-center text-[10px] text-muted-foreground">Choose full payment, a deposit, or pay at the spa during booking.</p></div></div></section>
  </InteriorPage>;
}

