export function ContactPage() {
  const [sent, setSent] = useState(false);
  function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); setSent(true); toast.success("Thank you. Our team will get back to you shortly."); }
  return <InteriorPage eyebrow="Come as you are" title="We'd love to welcome you." description="Questions about a ritual, a first visit, or simply finding us? We're here to help.">
    <section className="alba-section"><div className="alba-wrap grid gap-12 lg:grid-cols-[0.8fr_1.2fr]"><div className="grid content-start gap-7">{[[MapPin, "Find us", "Ahmedabad, Gujarat, India"], [Clock3, "Opening hours", "Monday - Sunday · 10:00 AM - 8:00 PM"], [Phone, "Call us", "+91 XXXXX XXXXX"], [MessageCircle, "Write to us", "hello@alba-wellness.com"]].map(([Icon, title, text]) => { const IconComponent = Icon as typeof MapPin; return <div key={title as string} className="flex gap-4"><IconComponent className="mt-1 size-4 text-forest"/><div><p className="text-sm font-medium">{title as string}</p><p className="mt-1 text-sm text-muted-foreground">{text as string}</p></div></div>; })}<div className="mt-3 flex aspect-[16/7] items-center justify-center border border-border bg-secondary/70"><div className="text-center"><MapPin className="mx-auto size-6 text-forest"/><p className="mt-2 text-xs">Ahmedabad, Gujarat</p><p className="mt-1 text-[10px] text-muted-foreground">ALBA WELLNESS · Open every day</p></div></div></div><form onSubmit={submit} className="grid content-start gap-5 border border-border bg-card p-6 sm:p-9"><div><p className="alba-eyebrow">A note to our team</p><h2 className="editorial-title mt-3 text-4xl">How can we help?</h2></div><div className="grid gap-2"><Label htmlFor="contact-name">Your name</Label><Input required id="contact-name" className={fieldClass} placeholder="Name"/></div><div className="grid gap-2 sm:grid-cols-2"><div className="grid gap-2"><Label htmlFor="contact-phone">Phone</Label><Input required id="contact-phone" type="tel" className={fieldClass} placeholder="+91"/></div><div className="grid gap-2"><Label htmlFor="contact-email">Email</Label><Input required id="contact-email" type="email" className={fieldClass} placeholder="you@example.com"/></div></div><div className="grid gap-2"><Label htmlFor="contact-message">Message</Label><textarea required id="contact-message" rows={4} className="resize-y border border-input bg-background px-3 py-3 text-sm outline-none focus-visible:ring-1 focus-visible:ring-ring" placeholder="Tell us a little about what you need"/></div><Button type="submit" className="h-11 rounded-none">{sent ? "MESSAGE RECEIVED" : "SEND YOUR NOTE"} <ArrowRight/></Button></form></div></section>
  </InteriorPage>;
}

function localDate(offset = 0) { return localIso(offset); }

export function BookingPage() {
  const { store, addBooking } = useAlbaDemo();
  const navigate = useNavigate();
  const search = new URLSearchParams(typeof window === "undefined" ? "" : window.location.search);
  const [step, setStep] = useState(0);
  const [serviceId, setServiceId] = useState(search.get("service") ?? "signature");
  const [date, setDate] = useState(localDate(1));
  const [time, setTime] = useState("");
  const [therapist, setTherapist] = useState("Any Available Therapist");
  const [addons, setAddons] = useState<string[]>([]);
  const [payMethod, setPayMethod] = useState("deposit");
  const [processing, setProcessing] = useState(false);
  const [card, setCard] = useState({ name: "", number: "", expiry: "", cvv: "" });
  const [payError, setPayError] = useState("");
  const [form, setForm] = useState({ name: store.profile.name, phone: store.profile.phone, email: store.profile.email, dob: store.profile.dob, note: "", firstVisit: true });
  const service = getService(store, serviceId);
  const total = service.price + service.addOns.filter((addon) => addons.includes(addon.name)).reduce((sum, addon) => sum + addon.price, 0);
  const steps = ["Treatment", "Date & time", "Therapist", "Extras", "Your details", "Payment"];
  const availableSlots = useMemo(() => slotStates(store, date, service.duration, therapist), [date, service.duration, store, therapist]);

  function next() {
    if (step === 0 && !serviceId) { toast.error("Please choose a treatment to continue."); return; }
    if (step === 1 && !time) { toast.error("Choose an available time for your visit."); return; }
    if (step === 4 && (!form.name.trim() || !form.phone.trim() || !/\S+@\S+\.\S+/.test(form.email))) { toast.error("Add your name, a phone number and a valid email."); return; }
    setStep((current) => Math.min(current + 1, 5));
  }

  async function confirm() {
    const chosen = availableSlots.find((slot) => slot.slot === time);
    if (!chosen || chosen.status === "Booked") { toast.error("That time is no longer available. Please choose another."); return; }
    if (payMethod !== "spa") {
      if (card.name.trim().length < 2 || card.number.replace(/\s/g, "").length < 12 || !/^\d{2}\/\d{2}$/.test(card.expiry) || card.cvv.length < 3) { toast.error("Add the cardholder name, card number, expiry and CVV to continue."); return; }
      if (card.number.replace(/\s/g, "").endsWith("0000")) { setPayError("Payment failed. Please try another card or pay at the spa."); { toast.error("Payment failed. No charge was made."); return; } }
    }
    setPayError("");
    setProcessing(true);
    await new Promise((resolve) => window.setTimeout(resolve, 1100));
    const payment = payMethod === "deposit" ? "Partial" as const : payMethod === "spa" ? "Pending" as const : "Paid" as const;
    const paidAmount = payment === "Paid" ? total : payment === "Partial" ? Math.round(total * (store.settings.depositPercent / 100)) : 0;
    addBooking({ customer: form.name, phone: form.phone, email: form.email, serviceId: service.id, date, time, therapist: assignTherapist(store, date, time, service.duration, therapist), amount: total, payment, paidAmount, notes: form.note, addons });
    setProcessing(false);
    toast.success("Appointment successfully booked.");
    navigate({ to: "/booking/success" });
  }

  return <AlbaLayout dark><section className="dark-panel min-h-[300px] pt-28"><div className="alba-wrap py-7"><p className="alba-eyebrow">Your moment of calm</p><h1 className="editorial-title mt-3 text-5xl sm:text-6xl">Make time for you.</h1><p className="mt-3 text-sm text-ivory/65">A few thoughtful steps, and your ritual is reserved.</p></div></section><section className="min-h-[70vh] py-8 sm:py-12"><div className="alba-wrap grid gap-8 lg:grid-cols-[minmax(0,1fr)_320px] lg:items-start"><div className="min-w-0"><div className="mb-8 grid grid-cols-6 gap-1 sm:gap-3">{steps.map((label, i) => <button key={label} type="button" onClick={() => i < step && setStep(i)} className="group min-w-0 text-left" aria-label={`Step ${i + 1}: ${label}${i === step ? " current" : ""}`}><span className={`mb-2 grid size-8 place-items-center border text-xs ${i <= step ? "border-forest bg-forest text-ivory" : "border-border text-muted-foreground"}`}>{i < step ? <Check className="size-4"/> : i + 1}</span><span className={`hidden truncate text-[10px] sm:block ${i === step ? "font-semibold text-foreground" : "text-muted-foreground"}`}>{label}</span></button>)}</div>
      <div className="border border-border bg-card p-5 sm:p-8">
        {step === 0 && <div><StepTitle title="Choose your treatment" note="A ritual to meet you where you are."/><div className="mt-6 grid gap-3">{store.services.filter((item) => item.active).map((item) => <button key={item.id} type="button" onClick={() => setServiceId(item.id)} className={`grid grid-cols-[88px_minmax(0,1fr)_auto] items-center gap-3 border p-3 text-left transition-colors sm:grid-cols-[104px_minmax(0,1fr)_auto] sm:gap-5 ${serviceId === item.id ? "border-forest bg-secondary/55" : "border-border hover:border-foreground/30"}`}><img src={albaImage(item.image)} alt="" width={1200} height={1008} className="aspect-square w-full object-cover"/><span className="min-w-0"><span className="block truncate text-sm font-medium">{item.name}</span><span className="mt-1 block text-xs text-muted-foreground">{item.duration} min · {item.category}</span><span className="mt-2 block text-sm">{formatRupees(item.price)}</span></span><span className={`grid size-5 place-items-center rounded-full border ${serviceId === item.id ? "border-forest bg-forest text-ivory" : "border-border"}`}>{serviceId === item.id && <Check className="size-3"/>}</span></button>)}</div></div>}
        {step === 1 && <div><StepTitle title="Choose a date & time" note="Select an available appointment. Past dates are not available."/><div className="mt-6 grid gap-5"><div className="grid gap-2"><Label htmlFor="booking-date">Appointment date</Label><Input id="booking-date" type="date" min={localDate(1)} value={date} onChange={(event) => { setDate(event.target.value); setTime(""); }} className={fieldClass}/></div><div><div className="mb-3 flex items-center gap-2 text-sm font-medium"><CalendarDays className="size-4 text-forest"/>{prettyDate(date)}</div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{availableSlots.map(({ slot, status }) => <button key={slot} disabled={status === "Booked"} type="button" onClick={() => setTime(slot)} className={`min-h-14 border px-3 py-2 text-left ${time === slot ? "border-forest bg-forest text-ivory" : status === "Booked" ? "border-border bg-secondary/40 text-muted-foreground opacity-50" : "border-border hover:border-forest"}`}><span className="block text-xs font-medium">{slot}</span><span className="mt-1 block text-[9px]">{time === slot ? "Selected" : status}</span></button>)}</div></div><p className="text-xs text-muted-foreground">Treatment time: {service.duration} minutes · We'll confirm your therapist in the next step.</p></div></div>}
        {step === 2 && <div><StepTitle title="A therapist for your ritual" note="Choose a specialist or leave it to us."/><div className="mt-6 grid gap-3 sm:grid-cols-2">{["Any Available Therapist", ...therapists].map((name, i) => <button key={name} type="button" onClick={() => setTherapist(name)} className={`flex min-h-20 items-center gap-3 border p-4 text-left ${therapist === name ? "border-forest bg-secondary/50" : "border-border hover:border-foreground/30"}`}><span className="grid size-10 shrink-0 place-items-center rounded-full bg-secondary text-forest">{i === 0 ? <UsersRound className="size-4"/> : <UserRound className="size-4"/>}</span><span className="min-w-0"><span className="block text-sm font-medium">{name}</span><span className="mt-1 block text-[10px] text-muted-foreground">{i === 0 ? "We'll find the right specialist" : store.staff.find((member) => member.name === name)?.specialty ?? "Wellness Therapist"}</span></span>{therapist === name && <Check className="ml-auto size-4 shrink-0 text-forest"/>}</button>)}</div></div>}
        {step === 3 && <div><StepTitle title="Make it your own" note="Optional additions to personalise your experience."/><div className="mt-6 grid gap-3">{service.addOns.map((addon) => <label key={addon.name} className="flex cursor-pointer items-center justify-between gap-4 border border-border p-4"><span className="flex items-center gap-3"><Checkbox checked={addons.includes(addon.name)} onCheckedChange={(checked) => setAddons((list) => checked ? [...list, addon.name] : list.filter((name) => name !== addon.name))}/><span><span className="block text-sm">{addon.name}</span><span className="mt-1 block text-[10px] text-muted-foreground">An optional finishing touch</span></span></span><span className="shrink-0 text-sm">+{formatRupees(addon.price)}</span></label>)}</div><button type="button" className="mt-5 text-xs text-muted-foreground underline underline-offset-4" onClick={() => setAddons([])}>Continue without additions</button></div>}
        {step === 4 && <div><StepTitle title="A few details, please" note="We'll use these to prepare for your visit."/><div className="mt-6 grid gap-4 sm:grid-cols-2">{[["Full name", "name", "text", "Your name"], ["Phone", "phone", "tel", "+91"], ["Email", "email", "email", "you@example.com"], ["Date of birth · optional", "dob", "date", ""]].map(([label, key, type, placeholder]) => <div key={key} className="grid gap-2"><Label htmlFor={`customer-${key}`}>{label}</Label><Input id={`customer-${key}`} type={type} placeholder={placeholder} required={key !== "dob"} value={form[key as keyof typeof form] as string} onChange={(event) => { const name = (key ?? "name") as keyof typeof form; setForm({ ...form, [name]: event.target.value }); }} className={fieldClass}/></div>)}<div className="grid gap-2 sm:col-span-2"><Label htmlFor="special-request">Special requests · optional</Label><textarea id="special-request" rows={3} value={form.note} onChange={(event) => setForm({ ...form, note: event.target.value })} placeholder="Anything you'd like us to know before your visit?" className="resize-y border border-input bg-background px-3 py-3 text-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"/></div><label className="flex items-center gap-3 text-xs text-muted-foreground sm:col-span-2"><Checkbox checked={form.firstVisit} onCheckedChange={(checked) => setForm({ ...form, firstVisit: checked === true })}/>This is my first visit to ALBA</label></div></div>}
        {step === 5 && <div><StepTitle title="Confirm your ritual" note="Choose how you'd like to take care of payment."/><div className="mt-6 grid gap-3">{[["full", "Pay full amount", total], ["deposit", `Pay ${store.settings.depositPercent}% deposit`, Math.round(total * (store.settings.depositPercent / 100))], ["spa", "Pay at the spa", 0]].map(([method, label, amount]) => <button key={method} type="button" onClick={() => setPayMethod(String(method))} className={`flex items-center justify-between border p-4 text-left ${payMethod === method ? "border-forest bg-secondary/45" : "border-border"}`}><span><span className="block text-sm font-medium">{label as string}</span><span className="mt-1 block text-[10px] text-muted-foreground">{method === "spa" ? "Settle at your appointment" : "Demo payment"}</span></span><span className="flex items-center gap-2 text-sm">{formatRupees(Number(amount))}<span className={`grid size-4 place-items-center rounded-full border ${payMethod === method ? "border-forest bg-forest text-ivory" : "border-border"}`}>{payMethod === method && <Check className="size-3"/>}</span></span></button>)}</div>{payMethod !== "spa" && <div className="mt-5 grid gap-3 sm:grid-cols-2"><p className="sm:col-span-2 text-[10px] tracking-[0.14em] text-muted-foreground">DEMO PAYMENT</p><div className="grid gap-2 sm:col-span-2"><Label htmlFor="card-name">Cardholder name</Label><Input id="card-name" value={card.name} onChange={(event) => setCard({ ...card, name: event.target.value })} className={fieldClass} placeholder="Name on card"/></div><div className="grid gap-2 sm:col-span-2"><Label htmlFor="card-number">Card number</Label><Input id="card-number" inputMode="numeric" value={card.number} onChange={(event) => setCard({ ...card, number: event.target.value })} className={fieldClass} placeholder="4242 4242 4242 4242"/></div><div className="grid gap-2"><Label htmlFor="card-expiry">Expiry</Label><Input id="card-expiry" value={card.expiry} onChange={(event) => setCard({ ...card, expiry: event.target.value })} className={fieldClass} placeholder="MM/YY"/></div><div className="grid gap-2"><Label htmlFor="card-cvv">CVV</Label><Input id="card-cvv" inputMode="numeric" value={card.cvv} onChange={(event) => setCard({ ...card, cvv: event.target.value })} className={fieldClass} placeholder="123"/></div></div>}{payError && <p className="mt-3 text-sm text-destructive">{payError}</p>}<div className="mt-6 flex items-start gap-3 border border-border bg-secondary/35 p-4"><ShieldCheck className="mt-0.5 size-4 shrink-0 text-forest"/><p className="text-xs leading-5 text-muted-foreground">{processing ? "Processing your demo payment..." : "This is a demo payment. No card will be charged and your details stay in this browser."}</p></div><div className="mt-6 border-t border-border pt-5"><p className="alba-eyebrow">Appointment summary</p><p className="mt-3 text-sm font-medium">{service.name}</p><p className="mt-1 text-xs text-muted-foreground">{prettyDate(date)} · {time || "Time to be chosen"} · {therapist}</p></div></div>}
        <div className="mt-8 flex flex-col-reverse gap-3 border-t border-border pt-5 sm:flex-row sm:justify-between">{step > 0 ? <Button variant="outline" className="rounded-none" onClick={() => setStep((current) => current - 1)}><ArrowLeft/> BACK</Button> : <span/>}{step < 5 ? <Button className="rounded-none" onClick={next}>CONTINUE <ArrowRight/></Button> : <Button className="rounded-none" disabled={processing} onClick={confirm}>{processing ? "RESERVING YOUR RITUAL..." : "CONFIRM APPOINTMENT"} <Check/></Button>}</div>
      </div></div>
      <aside className="lg:sticky lg:top-6"><div className="border border-border bg-card p-5 sm:p-6"><p className="alba-eyebrow">Your appointment</p><h2 className="mt-4 font-display text-3xl">{service.name}</h2><p className="mt-2 text-xs text-muted-foreground">{service.duration} minutes · {service.category}</p><div className="mt-5 grid gap-3 border-t border-border pt-4 text-xs"><p className="flex justify-between"><span className="text-muted-foreground">Treatment</span><span>{formatRupees(service.price)}</span></p>{service.addOns.filter((addon) => addons.includes(addon.name)).map((addon) => <p key={addon.name} className="flex justify-between"><span className="text-muted-foreground">{addon.name}</span><span>{formatRupees(addon.price)}</span></p>)}<p className="flex justify-between border-t border-border pt-3 text-sm font-semibold"><span>Total</span><span>{formatRupees(total)}</span></p></div><img src={albaImage("interior")} width={1200} height={1008} alt="Private ALBA Wellness room" className="mt-5 aspect-[16/9] w-full object-cover"/><p className="mt-4 text-[10px] leading-5 text-muted-foreground">A calm, private treatment room in Ahmedabad. Every day, 10:00 AM-8:00 PM.</p></div></aside></div></section></AlbaLayout>;
}

function StepTitle({ title, note }: { title: string; note: string }) { return <div><h2 className="font-display text-3xl sm:text-4xl">{title}</h2><p className="mt-2 text-xs text-muted-foreground">{note}</p></div>; }

export function BookingSuccessPage() {
  const { store } = useAlbaDemo();
  const booking = store.appointments.find((item) => item.id === store.lastBookingId) ?? store.appointments.find((item) => item.email === store.profile.email);
  const service = booking ? getService(store, booking.serviceId) : getService(store, "signature");
  function downloadInvoice() { if (!booking) return; downloadText(`${booking.invoiceNumber ?? booking.reference}.txt`, `ALBA WELLNESS\nKorean Head Spa & Wellness\n\nInvoice ${booking.invoiceNumber}\nBooking ${booking.reference}\nCustomer: ${booking.customer}\nService: ${service.name}\nTherapist: ${booking.therapist}\nDate: ${prettyDate(booking.date)} · ${booking.time}\nTotal: ${formatRupees(booking.amount)}\nPayment: ${booking.payment}\nTransaction: ${booking.txnId ?? "Pay at spa"}\n\nThank you for choosing ALBA WELLNESS.\nTechnology Platform by INFIYOURA`); toast.success("Invoice generated successfully."); }
  function downloadCalendar() { if (!booking) return; downloadText("alba-appointment.ics", calendarIcs(booking, service.name), "text/calendar"); toast.success("Appointment added to your calendar file."); }
  return <InteriorPage eyebrow="It's a date" title="You're all set." description="Your wellness experience has been reserved. We look forward to welcoming you." dark><section className="alba-section"><div className="alba-wrap max-w-3xl"><div className="border border-border bg-card p-6 sm:p-10"><div className="flex flex-col gap-5 border-b border-border pb-7 sm:flex-row sm:items-center sm:justify-between"><div><span className="grid size-12 place-items-center rounded-full bg-forest text-ivory"><Check/></span><p className="mt-4 text-xs text-muted-foreground">BOOKING REFERENCE</p><p className="mt-1 font-display text-3xl">{booking?.reference ?? "ALBA-2026-10482"}</p></div><div className="border border-forest/30 bg-forest/5 px-4 py-3 text-xs text-forest"><p>✓ Confirmation email prepared</p><p className="mt-2">✓ WhatsApp confirmation prepared</p><p className="mt-2">✓ Invoice generated</p></div></div><div className="grid gap-5 py-7 sm:grid-cols-2"><Summary label="Treatment" value={service.name}/><Summary label="Date & time" value={booking ? `${prettyDate(booking.date)} · ${booking.time}` : "To be confirmed"}/><Summary label="Therapist" value={booking?.therapist ?? "Maya Sharma"}/><Summary label="Guest" value={booking?.customer ?? store.profile.name}/><Summary label="Amount" value={formatRupees(booking?.amount ?? service.price)}/><Summary label="Payment status" value={booking?.payment ?? "Paid"}/></div><div className="flex flex-wrap gap-3 border-t border-border pt-6"><Button onClick={downloadInvoice} className="rounded-none"><Download/> DOWNLOAD INVOICE</Button><Button variant="outline" className="rounded-none" onClick={downloadCalendar}><CalendarDays/> ADD TO CALENDAR</Button><Button asChild variant="outline" className="rounded-none"><Link to="/customer/bookings">VIEW APPOINTMENT <ArrowRight/></Link></Button><Button variant="outline" className="rounded-none" onClick={() => toast.success(`WhatsApp confirmation sent to ${booking?.phone ?? store.profile.phone}.`)}>WHATSAPP</Button><Button variant="outline" className="rounded-none" onClick={() => toast.success(`Confirmation email sent to ${booking?.email ?? store.profile.email}.`)}>EMAIL</Button></div></div><p className="mt-6 text-center text-xs text-muted-foreground">{booking ? "Confirmation is ready for email and WhatsApp." : "Reserve a ritual and your confirmation will appear here."}</p><div className="mt-7 text-center"><Button asChild variant="link"><Link to="/">BACK TO ALBA <ArrowRight/></Link></Button></div></div></section></InteriorPage>;
}

function Summary({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] uppercase tracking-[0.12em] text-muted-foreground">{label}</p><p className="mt-1 text-sm">{value}</p></div>; }

export function LoginPage() {
  const { setRole } = useAlbaDemo();
  const navigate = useNavigate();
  const demoRoles = [["Super Admin", "admin@alba-wellness.demo"], ["Receptionist", "reception@alba-wellness.demo"], ["Therapist", "therapist@alba-wellness.demo"], ["Accountant", "accounts@alba-wellness.demo"]];
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  function enter(role: string) { setRole(role); toast.success(`Welcome to the ${role} demo.`); navigate({ to: role === "Therapist" ? "/staff" : role === "Customer" ? "/customer" : "/admin" }); }
  function signIn(event: React.FormEvent) { event.preventDefault(); const match = demoRoles.find((item) => item[1] === email.trim().toLowerCase()); if (!match || password !== "password") { toast.error("Those details are not recognised. Use a demo account and the password shown below."); return; } enter(match[0] ?? "Super Admin"); }
  return <AlbaLayout dark><section className="grid min-h-[82vh] bg-ink pt-[76px] text-ivory lg:grid-cols-2"><div className="relative hidden overflow-hidden lg:block"><img src={albaImage("interior")} width={1200} height={1008} alt="ALBA Wellness treatment room" className="absolute inset-0 h-full w-full object-cover opacity-80"/><div className="absolute inset-0 bg-ink/35"/><div className="absolute bottom-12 left-12 max-w-md"><p className="alba-eyebrow">A quieter kind of care</p><p className="editorial-title mt-4 text-5xl">Your moment<br/>is waiting.</p></div></div><div className="flex items-center justify-center px-5 py-12 sm:px-10"><div className="w-full max-w-md"><p className="alba-eyebrow">Welcome to ALBA</p><h1 className="editorial-title mt-4 text-5xl">Good to see you.</h1><p className="mt-3 text-sm text-ivory/60">Management portal. Choose a demo role, or sign in with the password shown below.</p><form onSubmit={signIn} className="mt-8 grid gap-3"><Input required type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="Email" className="h-11 rounded-none border-ivory/20 bg-transparent text-ivory placeholder:text-ivory/40"/><Input required type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Password" className="h-11 rounded-none border-ivory/20 bg-transparent text-ivory placeholder:text-ivory/40"/><Button type="submit" className="h-11 rounded-none bg-champagne text-ink">SIGN IN</Button></form><div className="mt-8 grid gap-3">{demoRoles.map(([role, email]) => <button key={role} onClick={() => enter(role ?? "Super Admin")} className="flex min-h-16 items-center justify-between border border-ivory/20 px-4 text-left transition-colors hover:border-champagne"><span><span className="block text-sm">{role}</span><span className="mt-1 block text-[10px] text-ivory/45">{email} · password</span></span><ArrowRight className="size-4 text-champagne"/></button>)}<button onClick={() => enter("Customer")} className="flex min-h-16 items-center justify-between border border-champagne/50 px-4 text-left hover:bg-ivory/5"><span><span className="block text-sm">Continue as Customer</span><span className="mt-1 block text-[10px] text-ivory/45">Meera Patel · customer portal</span></span><Heart className="size-4 text-champagne"/></button></div><p className="mt-6 text-[10px] leading-5 text-ivory/45">Demo accounts are ready to explore. No real password or account is required.</p><div className="mt-7 text-[9px] tracking-[0.15em] text-ivory/45">TECHNOLOGY PARTNER · INFÕ…YOURA</div></div></div></section><AlbaFooter/></AlbaLayout>;
}

const customerTabs = [
  ["Dashboard", "/customer", "overview"],
  ["My Appointments", "/customer/bookings", "bookings"],
  ["Booking History", "/customer/history", "history"],
  ["Invoices", "/customer/invoices", "invoices"],
  ["Profile", "/customer/profile", "profile"],
  ["Rewards", "/customer/rewards", "rewards"],
  ["Feedback", "/customer/feedback", "feedback"],
] as const;

export function CustomerPage({ view = "overview" }: { view?: string }) {
  const { store, updateStore, resetDemo, setRole } = useAlbaDemo();
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [profile, setProfile] = useState(store.profile);
  const [invoice, setInvoice] = useState<AlbaAppointment | null>(null);
  const [moving, setMoving] = useState<AlbaAppointment | null>(null);
  const [moveDate, setMoveDate] = useState(localIso(1));
  const [moveTime, setMoveTime] = useState("");
  const [cancelFor, setCancelFor] = useState<AlbaAppointment | null>(null);
  const [reason, setReason] = useState("");
  const [feedback, setFeedback] = useState({ rating: 5, quote: "", service: store.services[0]?.name ?? "Signature Korean Head Spa" });
  const appointments = store.appointments.filter((appointment) => appointment.customer === store.profile.name || appointment.email === store.profile.email);
  const upcoming = appointments.find((appointment) => appointment.status === "Confirmed" || appointment.status === "Pending" || appointment.status === "Rescheduled");
  const history = appointments.filter((appointment) => appointment.status === "Completed" || appointment.status === "Cancelled" || appointment.status === "No Show");
  const shown = (view === "history" ? history : appointments).filter((item) => `${item.reference} ${getService(store, item.serviceId).name}`.toLowerCase().includes(search.toLowerCase()));
  const points = appointments.filter((item) => item.status === "Completed").length * 120 + 80;
  function reschedule() {
    if (!moving || !moveTime) { toast.error("Choose a new date and time."); return; }
    const service = getService(store, moving.serviceId);
    const slot = slotStates(store, moveDate, service.duration, moving.therapist, moving.id).find((item) => item.slot === moveTime);
    if (!slot || slot.status === "Booked") { toast.error("That time is no longer available."); return; }
    updateStore((current) => ({ ...current, appointments: current.appointments.map((item) => item.id === moving.id ? { ...item, date: moveDate, time: moveTime, status: "Rescheduled" } : item), notifications: [{ id: `notice-${Date.now()}`, text: `Reschedule confirmation for ${moving.reference}`, read: false, time: "Just now" }, ...current.notifications] }));
    toast.success("Appointment rescheduled. Confirmation sent via WhatsApp & Email.");
    setMoving(null);
  }
  function cancel() {
    if (!cancelFor || !reason.trim()) { toast.error("Add a cancellation reason."); return; }
    updateStore((current) => ({ ...current, appointments: current.appointments.map((item) => item.id === cancelFor.id ? { ...item, status: "Cancelled", cancelReason: reason } : item) }));
    toast.success("Cancellation confirmation sent via WhatsApp & Email.");
    setCancelFor(null);
    setReason("");
  }
  return <AlbaLayout><section className="dark-panel pt-28"><div className="alba-wrap flex flex-col gap-5 py-8 sm:flex-row sm:items-end sm:justify-between"><div><p className="alba-eyebrow">DEMO MODE · CUSTOMER</p><h1 className="editorial-title mt-3 text-5xl">Hello, {store.profile.name.split(" ")[0]}.</h1><p className="mt-2 text-sm text-ivory/60">Your next moment of calm is closer than you think.</p></div><Button asChild className="w-fit rounded-none bg-champagne text-ink"><Link to="/booking">BOOK A RITUAL <ArrowRight/></Link></Button></div></section><section className="min-h-[65vh] py-8"><div className="alba-wrap grid gap-8 lg:grid-cols-[220px_minmax(0,1fr)]"><nav className="flex gap-2 overflow-x-auto border-b border-border pb-3 lg:block lg:border-b-0 lg:pb-0" aria-label="Customer navigation">{customerTabs.map(([label, to, id]) => <Link key={to} to={to} className={`shrink-0 px-3 py-2 text-xs no-underline lg:mb-1 lg:block ${view === id ? "bg-secondary text-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</Link>)}<button className="shrink-0 px-3 py-2 text-left text-xs text-muted-foreground lg:mt-4" onClick={() => { setRole("Guest"); toast.success("Signed out."); navigate({ to: "/" }); }}>Logout</button><button className="shrink-0 px-3 py-2 text-left text-xs text-muted-foreground" onClick={resetDemo}>Reset demo</button></nav><div className="min-w-0">
    {view === "overview" && <><SectionHeading eyebrow="Your ALBA moments" title="A little time, just for you." body="Your visits, thoughtful care and notes from the team, all in one place."/><div className="mt-7 grid grid-cols-2 gap-3 lg:grid-cols-4">{[["Upcoming", upcoming ? "1" : "-"], ["Previous visits", String(history.filter((item) => item.status === "Completed").length)], ["Total spent", formatRupees(appointments.reduce((sum, item) => sum + collectedAmount(item), 0))], ["Loyalty points", String(points)]].map(([label, value]) => <div key={label} className="border border-border bg-card p-4"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-2 font-display text-3xl">{value}</p></div>)}</div>{upcoming ? <AppointmentCard appointment={upcoming} store={store} onInvoice={() => setInvoice(upcoming)} onReschedule={() => { setMoving(upcoming); setMoveDate(upcoming.date); setMoveTime(upcoming.time); }} onCancel={() => setCancelFor(upcoming)}/> : <div className="mt-7 border border-border bg-card p-8 text-center"><CalendarDays className="mx-auto size-6 text-forest"/><p className="mt-3 font-display text-3xl">No upcoming appointments</p><p className="mt-2 text-xs text-muted-foreground">Your next wellness experience will appear here.</p><Button asChild className="mt-5 rounded-none"><Link to="/booking">FIND YOUR RITUAL</Link></Button></div>}</>}
    {(view === "bookings" || view === "history") && <><div className="grid grid-cols-[minmax(0,1fr)_auto] items-end gap-3"><div><p className="alba-eyebrow">{view === "history" ? "Earlier visits" : "Your visits"}</p><h2 className="editorial-title mt-2 text-4xl">{view === "history" ? "Booking history" : "Appointments"}</h2></div><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search visits" className="w-full max-w-48 rounded-none"/></div><div className="mt-6 grid gap-4">{shown.map((appointment) => <AppointmentCard key={appointment.id} appointment={appointment} store={store} onInvoice={() => setInvoice(appointment)} onReschedule={() => { setMoving(appointment); setMoveDate(appointment.date); }} onCancel={() => setCancelFor(appointment)}/>)}{shown.length === 0 && <div className="border border-border bg-card p-8 text-center"><p className="font-display text-3xl">Nothing here yet</p><p className="mt-2 text-xs text-muted-foreground">Your next wellness experience will appear here.</p></div>}</div></>}
    {view === "profile" && <><p className="alba-eyebrow">Your details</p><h2 className="editorial-title mt-2 text-4xl">Profile</h2><div className="mt-6 grid gap-4 border border-border bg-card p-6 sm:grid-cols-2">{([["Name", "name"], ["Phone", "phone"], ["Email", "email"], ["Date of birth", "dob"], ["Address", "address"], ["Preferences", "preferences"]] as const).map(([label, key]) => <div key={key} className="grid gap-2"><Label htmlFor={`profile-${key}`}>{label}</Label><Input id={`profile-${key}`} type={key === "dob" ? "date" : "text"} value={profile[key]} onChange={(event) => setProfile({ ...profile, [key]: event.target.value })} className={fieldClass}/></div>)}<div className="flex items-end"><Button className="rounded-none" onClick={() => { updateStore((current) => ({ ...current, profile, appointments: current.appointments.map((item) => item.email === current.profile.email || item.customer === current.profile.name ? { ...item, customer: profile.name, phone: profile.phone, email: profile.email } : item) })); toast.success("Your profile has been updated."); }}>SAVE CHANGES <Check/></Button></div></div></>}
    {view === "invoices" && <><p className="alba-eyebrow">Your records</p><h2 className="editorial-title mt-2 text-4xl">Invoices</h2><div className="mt-6 grid gap-3">{appointments.map((item) => <div key={item.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3 border border-border bg-card p-4 sm:grid-cols-[1.2fr_1fr_auto]"><span className="min-w-0"><span className="block truncate text-xs font-medium">{item.invoiceNumber}</span><span className="mt-1 block text-[10px] text-muted-foreground">{prettyDate(item.date)} · {getService(store, item.serviceId).name}</span></span><span className="text-xs">{formatRupees(item.amount)} · {item.payment}</span><span className="flex gap-2"><Button variant="outline" size="sm" onClick={() => setInvoice(item)}>View</Button><Button variant="outline" size="sm" onClick={() => { downloadText(`${item.invoiceNumber}.txt`, `${item.invoiceNumber}\n${item.customer}\n${formatRupees(item.amount)}`); toast.success("Invoice downloaded."); }}><Download/></Button><Button variant="outline" size="sm" onClick={() => toast.success("Invoice link copied for sharing.")}>Share</Button></span></div>)}</div></>}
    {view === "rewards" && <div className="border border-border bg-card p-6"><p className="alba-eyebrow">ALBA moments</p><h2 className="editorial-title mt-2 text-4xl">{points} points</h2><p className="mt-3 text-sm text-muted-foreground">Points gather with every completed ritual. 500 points unlocks a scalp serum ritual on your next visit.</p><div className="mt-5 h-2 bg-secondary"><div className="h-full bg-forest" style={{ width: `${Math.min(100, points / 5)}%` }}/></div></div>}
    {view === "feedback" && <form className="grid max-w-xl gap-4 border border-border bg-card p-6" onSubmit={(event) => { event.preventDefault(); if (feedback.quote.trim().length < 8) { toast.error("Share a few words about your visit."); return; } updateStore((current) => ({ ...current, reviews: [{ id: `review-${Date.now()}`, customer: store.profile.name, service: feedback.service, therapist: "Maya Sharma", quote: feedback.quote, rating: feedback.rating, featured: false, status: "Pending", date: localIso(0) }, ...current.reviews] })); toast.success("Thank you. Your note is with the ALBA team."); setFeedback({ ...feedback, quote: "" }); }}><p className="alba-eyebrow">A note for the team</p><h2 className="editorial-title text-4xl">Feedback</h2><select aria-label="Treatment" value={feedback.service} onChange={(event) => setFeedback({ ...feedback, service: event.target.value })} className="h-11 border border-border bg-background px-3 text-sm">{store.services.map((service) => <option key={service.id}>{service.name}</option>)}</select><div className="flex gap-2">{[1, 2, 3, 4, 5].map((score) => <button type="button" key={score} onClick={() => setFeedback({ ...feedback, rating: score })} className={`size-10 border ${feedback.rating >= score ? "border-champagne bg-champagne/30" : "border-border"}`}>{score}</button>)}</div><textarea required value={feedback.quote} onChange={(event) => setFeedback({ ...feedback, quote: event.target.value })} rows={4} className="border border-input px-3 py-2 text-sm" placeholder="How did your ritual feel?"/><Button className="rounded-none">SEND FEEDBACK</Button></form>}
    </div></div></section>{moving && <div className="fixed inset-0 z-50 grid place-items-center bg-ink/50 p-4"><div className="w-full max-w-md bg-background p-6"><p className="font-display text-3xl">Reschedule</p><div className="mt-4 grid gap-3"><Input type="date" min={localIso(0)} value={moveDate} onChange={(event) => setMoveDate(event.target.value)} className={fieldClass}/><div className="grid grid-cols-2 gap-2">{slotStates(store, moveDate, getService(store, moving.serviceId).duration, moving.therapist, moving.id).map((slot) => <button key={slot.slot} type="button" disabled={slot.status === "Booked"} onClick={() => setMoveTime(slot.slot)} className={`border px-2 py-3 text-xs ${moveTime === slot.slot ? "border-forest bg-forest text-ivory" : "border-border"}`}>{slot.slot}<span className="mt-1 block text-[9px]">{slot.status}</span></button>)}</div></div><div className="mt-4 flex gap-2"><Button variant="outline" className="rounded-none" onClick={() => setMoving(null)}>Close</Button><Button className="rounded-none" onClick={reschedule}>Confirm new time</Button></div></div></div>}{cancelFor && <div className="fixed inset-0 z-50 grid place-items-center bg-ink/50 p-4"><div className="w-full max-w-md bg-background p-6"><p className="font-display text-3xl">Cancel this visit?</p><p className="mt-2 text-sm text-muted-foreground">Tell us a little about why, so we can look after the time.</p><textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={3} className="mt-4 w-full border border-input px-3 py-2 text-sm" placeholder="Cancellation reason"/><div className="mt-4 flex gap-2"><Button variant="outline" className="rounded-none" onClick={() => setCancelFor(null)}>Keep appointment</Button><Button className="rounded-none" onClick={cancel}>Confirm cancellation</Button></div></div></div>}<InvoiceDialog appointment={invoice} onClose={() => setInvoice(null)}/></AlbaLayout>;
}

function AppointmentCard({ appointment, store, onCancel, onInvoice, onReschedule }: { appointment: AlbaAppointment; store: import("@/lib/alba-demo").AlbaDemoStore; onCancel: () => void; onInvoice: () => void; onReschedule: () => void }) {
  const service = getService(store, appointment.serviceId);
  const open = appointment.status === "Confirmed" || appointment.status === "Pending" || appointment.status === "Rescheduled";
  return <article className="mt-6 grid gap-4 border border-border bg-card p-5 sm:grid-cols-[1fr_auto] sm:items-center sm:p-6"><div><div className="flex flex-wrap items-center gap-3"><p className="font-display text-3xl">{service.name}</p><span className="border border-forest/30 px-2 py-1 text-[9px] uppercase tracking-[0.1em] text-forest">{appointment.status}</span></div><div className="mt-3 flex flex-wrap gap-x-5 gap-y-2 text-xs text-muted-foreground"><span className="inline-flex items-center gap-2"><CalendarDays className="size-3.5"/>{prettyDate(appointment.date)}</span><span className="inline-flex items-center gap-2"><Clock3 className="size-3.5"/>{appointment.time}</span><span>{appointment.therapist}</span></div><p className="mt-2 text-[10px] text-muted-foreground">{appointment.reference} · {formatRupees(appointment.amount)} · {appointment.payment}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={onInvoice}>VIEW</Button>{open && <Button size="sm" variant="outline" onClick={onReschedule}>RESCHEDULE</Button>}{open && <Button size="sm" variant="outline" onClick={onCancel}>CANCEL</Button>}</div></article>;
}

export function AdminPage({ view = "overview" }: { view?: string }) {
  const { store, role, setRole } = useAlbaDemo();
  const navigate = useNavigate();
  const [creating, setCreating] = useState(false);
  const links = navFor(store, role);
  const revenue = store.appointments.reduce((sum, item) => sum + collectedAmount(item), 0);
  useEffect(() => { if (role === "Therapist") navigate({ to: "/staff" }); }, [navigate, role]);
  const todayCount = store.appointments.filter((item) => item.date === localIso(0) || item.date === localIso(1)).length;
  return <div className="min-h-screen bg-secondary/35"><div className="grid min-h-screen lg:grid-cols-[244px_minmax(0,1fr)]"><aside className="dark-panel hidden flex-col p-5 lg:flex"><Link to="/" className="flex items-center gap-3 text-ivory no-underline"><span className="grid size-9 place-items-center border border-champagne/70 font-display text-xl text-champagne">A</span><span className="text-[11px] tracking-[0.16em]">ALBA WELLNESS</span></Link><p className="alba-eyebrow mt-9">MANAGEMENT</p><nav className="mt-3 grid gap-1">{links.map(([label, to]) => <Link key={to} to={to} className={`px-3 py-2.5 text-xs no-underline ${view === (to === "/admin" ? "overview" : to.split("/").at(-1)) ? "bg-ivory/10 text-champagne" : "text-ivory/65 hover:bg-ivory/5 hover:text-ivory"}`}>{label}</Link>)}</nav><div className="mt-auto border-t border-ivory/10 pt-4"><p className="text-[10px] text-ivory/45">Technology partner</p><p className="mt-1 text-[10px] font-semibold tracking-[0.16em] text-ivory/70">INFIYOURA</p><Link to="/" className="mt-4 block text-[10px] text-ivory/45 no-underline hover:text-ivory">← Back to public site</Link></div></aside><main className="min-w-0"><header className="sticky top-0 z-20 flex min-h-[68px] items-center justify-between gap-3 border-b border-border bg-background/95 px-4 backdrop-blur sm:px-8"><div className="flex min-w-0 items-center gap-3"><Button asChild variant="ghost" size="icon" className="shrink-0 lg:hidden"><Link to="/"><ArrowLeft/></Link></Button><div className="min-w-0"><p className="truncate text-[10px] text-muted-foreground">ALBA WELLNESS · DEMO MODE</p><p className="truncate text-sm font-medium">Good morning, {role === "Guest" ? "Admin" : role}</p></div></div><div className="flex shrink-0 items-center gap-2"><NotificationBell/><select aria-label="Demo role" value={role === "Guest" ? "Super Admin" : role} onChange={(event) => { const next = event.target.value; setRole(next); if (next === "Therapist") navigate({ to: "/staff" }); }} className="max-w-36 border border-border bg-background px-2 py-2 text-[10px]"><option>Super Admin</option><option>Receptionist</option><option>Therapist</option><option>Accountant</option></select><Button size="sm" className="rounded-none" onClick={() => setCreating(true)}><Plus/> NEW</Button></div></header><nav className="flex gap-1 overflow-x-auto border-b border-border bg-background px-3 py-2 lg:hidden">{links.map(([label, to]) => <Link key={to} to={to} className="shrink-0 px-3 py-2 text-[10px] text-muted-foreground no-underline">{label}</Link>)}</nav><div className="p-4 sm:p-7 lg:p-9">
    {view === "overview" && <><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="alba-eyebrow">ALBA WELLNESS · MANAGEMENT</p><h1 className="editorial-title mt-2 text-4xl sm:text-5xl">Good morning.</h1><p className="mt-2 text-xs text-muted-foreground">{new Date().toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}</p></div></div><div className="mt-7 grid grid-cols-2 gap-3 xl:grid-cols-4">{[["Total bookings", store.appointments.length], ["Today & tomorrow", todayCount], ["Upcoming", store.appointments.filter((item) => item.status === "Confirmed" || item.status === "Rescheduled").length], ["Completed", store.appointments.filter((item) => item.status === "Completed").length], ["Cancelled", store.appointments.filter((item) => item.status === "Cancelled").length], ["Revenue", formatRupees(revenue)], ["Pending payments", store.appointments.filter((item) => item.payment === "Pending" || item.payment === "Partial").length], ["Guests", new Set(store.appointments.map((item) => item.email)).size]].map(([label, value]) => <div key={String(label)} className="border border-border bg-background p-4 sm:p-5"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-2 font-display text-3xl sm:text-4xl">{value}</p></div>)}</div><div className="mt-8"><TrendCharts rows={store.appointments}/></div></>}
    {view === "appointments" && <AppointmentBoard/>}
    {view === "calendar" && <CalendarStudio/>}
    {view === "services" && <ServiceStudio/>}
    {view === "staff" && <StaffStudio/>}
    {view === "customers" && <CustomerStudio/>}
    {view === "invoices" && <InvoiceStudio/>}
    {view === "payments" && <InvoiceStudio payments/>}
    {view === "offers" && <OfferStudio/>}
    {view === "reviews" && <ReviewStudio/>}
    {view === "marketing" && <MarketingStudio/>}
    {view === "gallery" && <ContentStudio focus="gallery"/>}
    {view === "content" && <ContentStudio focus="content"/>}
    {view === "reports" && <ReportStudio/>}
    {view === "roles" && <RolesStudio/>}
    {view === "audit" && <AuditStudio/>}
    {view === "settings" && <SettingsStudio/>}
    </div></main></div><NewBookingDialog open={creating} onClose={() => setCreating(false)}/></div>;
}
